using Microsoft.EntityFrameworkCore;

public sealed class ReserveStock(InventoryDb db)
{
    public async Task CompensateAsync(SagaStep step, CancellationToken ct)
    {
        var item = await db.Items.SingleAsync(i => i.Sku == step.Sku, ct);
        // "Roll back" by restoring the value read before the reservation.
        // A delivery committed in between is silently erased
        item.Available = step.AvailableBefore;
        await db.SaveChangesAsync(ct);
    }
}

using Microsoft.EntityFrameworkCore;

public sealed class ReserveStock(InventoryDb db)
{
    public async Task CompensateAsync(Guid reservationId, CancellationToken ct)
    {
        var r = await db.Reservations.FindAsync([reservationId], ct);
        if (r is null || r.Released) return; // already compensated: no-op

        var item = await db.Items.SingleAsync(i => i.Sku == r.Sku, ct);
        item.Available += r.Quantity; // reverse only our own effect
        r.Released = true;
        // Available is a concurrency token: a clash throws, and the step retries
        await db.SaveChangesAsync(ct);
    }
}
